class CodePathValidator {

    private static final Logger log = Logger.getLogger(CodePathValidator.class.getName());

    boolean exists(char[][] grid, String word) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (dfs(grid, r, c, word, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfs(char[][] grid, int r, int c, String word, int idx) {
        if (idx == word.length()) return true;          // all letters matched
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) return false;
        if (grid[r][c] != word.charAt(idx)) return false;

        char original = grid[r][c];
        grid[r][c] = '#';                               // mark visited
        boolean found = dfs(grid, r + 1, c, word, idx + 1)
                     || dfs(grid, r - 1, c, word, idx + 1)
                     || dfs(grid, r, c + 1, word, idx + 1)
                     || dfs(grid, r, c - 1, word, idx + 1);
        grid[r][c] = original;                          // restore — backtrack
        return found;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
